def sha(p):
 h=hashlib.sha256()
 with Path(p).open('rb') as f:
  for block in iter(lambda:f.read(8388608),b''):h.update(block)
 return h.hexdigest()
def main():
 R=Path(os.environ['PANCANCER_PREFLIGHT_ROOT']);AR=Path(os.environ['PANCANCER_ANNOTATION_ROOT']);P=R/'immune_same_name_family_source_review_v1';U=AR/'20261010_uniform_expression_annotation_v1';B=AR/'20261010_expression_annotation_downstream_v1';O=P/'major_pair_native_assembly_v1';planpath=Path(os.environ['PANCANCER_MAJOR_NATIVE_PLAN']);plan=json.loads(planpath.read_text());assert sha(__file__)==plan['producer_sha256'] and not O.exists();start=datetime.now(timezone.utc).isoformat()
 paths=dict(counts=B/'inputs/sample_major_subcluster_counts.tsv',catalogue=B/'downstream_review_v2/number_to_annotation_dictionary.tsv',scope=P/'patient_block_provenance_overlay_v1/private_all1290_patient_provenance_overlay.tsv')
 for k,f in paths.items():assert sha(f)==plan['current_input_sha256'][k]
 for n,h in plan['native_cache']['root_files'].items():assert sha(U/n)==h
 coverage=P/'major_pair_coverage_probe_v1/all_authoritative_major_pair_context_coverage.tsv';assert sha(coverage)==plan['coverage_sha256'];cov=pd.read_csv(coverage,sep='\t');cov=cov[cov.coverage_ge20libraries_ge10blocks].sort_values(['stratum','major1','major2']).reset_index(drop=True);assert len(cov)==138;scope=pd.read_csv(paths['scope'],sep='\t',keep_default_na=False).set_index('sampleID');counts=pd.read_csv(paths['counts'],sep='\t');counts=counts[counts.sampleID.isin(scope.index)];current=pd.read_csv(paths['catalogue'],sep='\t').set_index('node_id');original=pd.read_csv(U/'all_node_number_catalog.tsv',sep='\t');assert (counts.majorCluster.to_numpy()==current.set_index('subCluster').loc[counts.subCluster,'majorCluster'].to_numpy()).all();majors=counts.groupby(['sampleID','majorCluster']).n_cells.sum().unstack(fill_value=0).reindex(scope.index,fill_value=0)
 resource=pd.read_csv(Path(os.environ['PANCANCER_FROZEN_LR_RESOURCE']),sep='\t');assert sha(Path(os.environ['PANCANCER_FROZEN_LR_RESOURCE']))==plan['resource_sha256'] and len(resource)==4624;lrgenes={g for pair in resource.itertuples(index=False,name=None) for v in pair for g in v.split('_')};breast_mapping=P/'GSE161529_official_metadata_recon_v2/private_all69_official_metadata_exact_mapping.tsv';assert sha(breast_mapping)==plan['breast_mapping_sha256'];breast=pd.read_csv(breast_mapping,sep='\t',dtype=str,keep_default_na=False).set_index('sampleID');queries={};groups=[]
 for ix,r in cov.iterrows():
  m=scope.stratum.eq(r.stratum)&scope.analysis_eligible&majors[r.major1].ge(20)&majors[r.major2].ge(20);samples=scope.index[m].to_numpy(dtype=str);meta=scope.loc[samples];assert len(samples)==r.n_endpoint_libraries and meta.effective_resampling_block.nunique()==r.n_analysis_blocks
  for direction,(s,t) in enumerate([(r.major1,r.major2),(r.major2,r.major1)]):
   gid='MAJ'+str(ix*2+direction+1).zfill(3);groups.append(dict(group_id=gid,gse_id=r.gse_id,stratum=r.stratum,cancerType=r.cancerType,sample_class=r.sample_class,source=s,target=t,samples=samples,meta=meta));queries.setdefault(r.gse_id,set()).update((sample,major) for sample in samples for major in [s,t])
 O.mkdir();(O/'private_source_major_arrays').mkdir();(O/'private_group_arrays').mkdir();summaries=[];group_rows=[];case_total=0;case_handle=gzip.open(O/'all1276224_native_LR_case_readiness.tsv.gz','wt',newline='');case_writer=None
 for sid,keys in sorted(queries.items()):
  root=U/'by_gse'/sid;ex=plan['native_cache']['sources'][sid];assert sha(root/'manifest.json')==ex['manifest_sha256'];inv=json.loads((root/'manifest.json').read_text());assert inv['status']=='COMPLETE_EXACT_MEMBER_EXPRESSION_EVIDENCE'
  for n,h in inv['output_sha256'].items():assert sha(root/n)==h
  units=pd.read_csv(root/'units.tsv',sep='\t',keep_default_na=False);assert np.array_equal(units.unit_row,np.arange(len(units)));genes=pd.read_csv(root/'genes.tsv',sep='\t').gene.to_numpy(dtype=str);assert pd.Index(genes).is_unique;selected=units[units.candidate_eligible & units.sample_uid.isin(scope.index)].copy();selected['node_id']=original.node_id.to_numpy()[selected.node_index];assert selected.node_id.isin(current.index).all();selected['subCluster']=current.loc[selected.node_id,'subCluster'].to_numpy();selected['majorCluster']=current.loc[selected.node_id,'majorCluster'].to_numpy();expected=counts[counts.sampleID.isin(selected.sample_uid)].set_index(['sampleID','subCluster']).n_cells;ix=selected.set_index(['sample_uid','subCluster']);assert ix.index.is_unique and set(ix.index)==set(expected.index) and np.array_equal(ix.n_cells,expected.loc[ix.index].to_numpy());keys=sorted(keys);keyindex={k:i for i,k in enumerate(keys)};take=selected[[v in keyindex for v in zip(selected.sample_uid,selected.majorCluster)]];ri=[keyindex[v] for v in zip(take.sample_uid,take.majorCluster)];A=csr_matrix((np.ones(len(take)),(ri,take.unit_row.to_numpy())),shape=(len(keys),len(units)));nc=np.asarray(A@units.n_cells.to_numpy()).ravel().astype(int);assert np.array_equal(nc,[majors.loc[s,m] for s,m in keys]) and (nc>=20).all();logs=load_npz(root/'sum_log1p_CP10K.npz').tocsr();positive=load_npz(root/'positive_counts.npz').tocsr();assert logs.shape==positive.shape==(len(units),len(genes));sumlog=(A@logs).tocsr();sumpositive=(A@positive).tocsr();meanlog=sumlog.multiply(1/nc[:,None]).tocsr();pct=sumpositive.multiply(1/nc[:,None]).tocsr();assert (pct.data>=0).all() and (pct.data<=1+1e-12).all();nonlr=~pd.Index(genes).isin(lrgenes);nd=np.asarray(sumpositive[:,nonlr].sum(axis=1)).ravel()/nc;lc=np.asarray(sumlog[:,nonlr].sum(axis=1)).ravel()/nc
  meta=pd.DataFrame([dict(unit_row=i,sampleID=s,majorCluster=m,n_cells=int(nc[i])) for i,(s,m) in enumerate(keys)]);meta.to_csv(O/'private_source_major_arrays'/(sid+'_units.tsv'),sep='\t',index=False);save_npz(O/'private_source_major_arrays'/(sid+'_meanlog.npz'),meanlog);save_npz(O/'private_source_major_arrays'/(sid+'_pct_positive.npz'),pct);np.savez_compressed(O/'private_source_major_arrays'/(sid+'_axes.npz'),genes=genes,mean_detected_nonLR_genes=nd,mean_sum_log_nonLR_genes=lc);gi={g:i for i,g in enumerate(genes)};components=sorted(lrgenes&set(genes));cols=[gi[g] for g in components];dense=meanlog[:,cols].toarray();detections=pct[:,cols].toarray();cc={g:i for i,g in enumerate(components)};measured=np.array([set(l.split('_')+r.split('_')).issubset(gi) for l,r in resource.itertuples(index=False,name=None)])
